def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    def seg(L, T, B):
        if L == 1:
            return [T]
        items = [T]
        for _ in range((L - 1) // 2):
            x = rng.randint(-B, B)
            items += [x, -x]
        if (L - 1) % 2:
            items.append(0)
        rng.shuffle(items)
        return items

    def build(L1, L2, L3, T1, T2, T3, B):
        s1 = rng.randint(-B, B)
        s2 = rng.randint(-B, B)
        return seg(L1, T1, B) + [s1] + seg(L2, T2, B) + [s2] + seg(L3, T3, B)

    tests = [fmt([7]), fmt([5, 5, 5, 5]), fmt([1, 1, 1, 1, 1]), fmt([0] * 5), fmt([0] * 6),
             fmt([1, 2, 1, 2, 1, 2, 1]), fmt([3, 9, 1, 2, 5, 3]), fmt([-1, 50, -1, 50, -1]),
             fmt([0, 7, 0, 7, 0]), fmt([2, 0, 2, 100, 2, -50, 2, 1])]
    for n in range(5, 13):
        for _ in range(3):
            tests.append(fmt([rng.randint(-2, 2) for _ in range(n)]))
    for _ in range(14):
        T = rng.randint(-3, 3)
        tests.append(fmt(build(rng.randint(1, 4), rng.randint(1, 4), rng.randint(1, 4), T, T, T, 3)))
    for _ in range(6):
        T = rng.randint(-3, 3)
        tests.append(fmt(build(rng.randint(1, 4), rng.randint(1, 4), rng.randint(1, 4), T, T, T + 1, 3)))
    B = 10**9
    T = rng.randint(-B + 1, B - 1)
    tests.append(fmt(build(33333, 33333, 33332, T, T, T, B)))
    tests.append(fmt(build(33333, 33333, 33332, T, T, T + 1, B)))
    tests.append(fmt(build(1, 99996, 1, T, T, T, B)))
    tests.append(fmt([0] * 100000))
    tests.append(fmt([rng.randint(-B, B) for _ in range(100000)]))
    tests.append(fmt([rng.randint(-1, 1) for _ in range(100000)]))
    return tests
